using System.Windows; using System.Windows.Controls; namespace WpfSemana02; public partial class ReporteIngresosWindow:Window{public ReporteIngresosWindow(){InitializeComponent();cboEstado.SelectedIndex=0;Mostrar(Datos.Ingresos);}private void Buscar_Click(object s,RoutedEventArgs e){IEnumerable<Ingreso> q=Datos.Ingresos;if(dpInicio.SelectedDate is DateTime a)q=q.Where(x=>x.FechaHora.Date>=a.Date);if(dpFin.SelectedDate is DateTime b)q=q.Where(x=>x.FechaHora.Date<=b.Date);var t=txtBuscar.Text.Trim();if(t.Length>0)q=q.Where(x=>x.Placa.Contains(t,StringComparison.OrdinalIgnoreCase)||x.Conductor.Contains(t,StringComparison.OrdinalIgnoreCase)||x.Cliente.Contains(t,StringComparison.OrdinalIgnoreCase)||x.Producto.Contains(t,StringComparison.OrdinalIgnoreCase));var estado=((ComboBoxItem)cboEstado.SelectedItem).Content.ToString();if(estado=="En patio")q=q.Where(x=>!x.FechaSalida.HasValue);else if(estado=="Finalizado")q=q.Where(x=>x.FechaSalida.HasValue);Mostrar(q.ToList());}private void Limpiar_Click(object s,RoutedEventArgs e){dpInicio.SelectedDate=null;dpFin.SelectedDate=null;txtBuscar.Clear();cboEstado.SelectedIndex=0;Mostrar(Datos.Ingresos);}private void Mostrar(IEnumerable<Ingreso> q){var l=q.ToList();dgReporte.ItemsSource=l;txtResumen.Text=$"Registros: {l.Count}   |   Peso ingresado: {l.Sum(x=>x.Peso):N2} kg   |   Peso neto: {l.Sum(x=>x.PesoNeto):N2} kg";}}
